// Portable visual skill timeline. No combat, wallet, networking, eval or globals.
export const SKILL_RUNTIME_VERSION=2;
export const SKILL_MOTIONS=Object.freeze({still:'Tại chỗ',expand:'Nở rộng',shrink:'Thu nhỏ',pulse:'Nhịp phồng / co',spin:'Xoay vòng',orbit:'Lượn quanh điểm neo',spiral:'Xoắn ốc ra ngoài',rise:'Bay lên',fall:'Rơi xuống điểm neo',sway:'Lắc ngang',shake:'Rung nhẹ',move:'Trượt theo độ lệch',projectile:'Bay người phát → mục tiêu',arc:'Bay theo vòng cung',boomerang:'Bay đi rồi quay về'});
export const SKILL_EASINGS=Object.freeze({linear:'Đều',in:'Nhanh dần',out:'Chậm dần',inOut:'Êm đầu và cuối'});
export function motionDefaults(motion){return {amplitude:motion==='shake'?8:60,cycles:motion==='shake'?5:2,turns:1,travelX:120,travelY:['rise','fall'].includes(motion)?120:0,easing:'linear'}}
export const skillId=id=>typeof id==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(id)&&!['__proto__','constructor','prototype'].includes(id);
const sf=(n,a,b)=>Number.isFinite(n)&&n>=a&&n<=b,err=s=>{throw Error(s)},srcOK=s=>typeof s==='string'&&(/^assets\/[\w./-]+\.(png|webp|jpg|jpeg)$/.test(s)&&!s.split('/').includes('..')||/^data:image\/(png|webp);base64,[A-Za-z0-9+/=]+$/.test(s));
export function createSkillProject(){return {format:'darkin-skill-project-v1',id:'my_skills',name:'Kỹ năng của tôi',skills:{},effects:{}}}
export function validateSkillProject(data){
 const p=data?.format==='darkin-skill-pack-v1'?data.project:data;if(!p||p.format!=='darkin-skill-project-v1'||!skillId(p.id)||typeof p.name!=='string'||!p.name.trim()||p.name.length>150||!p.skills||Array.isArray(p.skills)||!p.effects||Array.isArray(p.effects)||Object.keys(p.skills).length>256||Object.keys(p.effects).length>512)err('Không đúng project/gói Skill & VFX');let frames=0;
 for(const[id,e]of Object.entries(p.effects)){if(!skillId(id)||e?.id!==id||typeof e.name!=='string'||e.name.length>150||!['image','frames','procedural'].includes(e.group))err('Hiệu ứng không hợp lệ: '+id);if(e.group==='procedural'){if(!['ring','slash','beam','sparks'].includes(e.primitive)||!/^#[0-9a-fA-F]{6}$/.test(e.color))err('Mẫu VFX không hợp lệ')}else{if(!Array.isArray(e.frames)||!e.frames.length||e.frames.length>128)err('Hiệu ứng cần 1–128 frame');for(const f of e.frames){if(!f||!srcOK(f.src)||!sf(f.w,1,4096)||!sf(f.h,1,4096)||!sf(f.ax,-4,4)||!sf(f.ay,-4,4)||!sf(f.duration,.001,30))err('Frame VFX không hợp lệ: '+id);frames++}}}if(frames>2048)err('Tối đa 2048 frame VFX trong một gói');
 for(const[id,s]of Object.entries(p.skills)){if(!skillId(id)||s?.id!==id||typeof s.name!=='string'||!s.name.trim()||s.name.length>150||!['active','buff','passive'].includes(s.kind)||!sf(s.duration,.1,30)||!sf(s.cooldown,0,3600)||!sf(s.cost,0,1e6)||!sf(s.range,0,4096)||!sf(s.hitAt,0,s.duration)||typeof s.animation!=='string'||s.animation.length>100||!Array.isArray(s.events)||s.events.length>128)err('Kỹ năng không hợp lệ: '+id);const ids=new Set();for(const e of s.events){if(!e||!skillId(e.id)||ids.has(e.id)||!Object.hasOwn(p.effects,e.effectId)||!sf(e.at,0,s.duration)||!sf(e.duration,.01,30)||e.at+e.duration>s.duration+1e-8||!sf(e.scale,.01,10)||!sf(e.x,-4096,4096)||!sf(e.y,-4096,4096)||!sf(e.rotation,-3600,3600)||!sf(e.opacity,0,1)||!['caster','target','world'].includes(e.anchor)||!['low','high','glow'].includes(e.layer)||!['normal','add'].includes(e.blend)||!Object.hasOwn(SKILL_MOTIONS,e.motion)||typeof e.follow!=='boolean')err('Mốc hiệu ứng sai/thừa thời lượng: '+id);
  for(const[k,min,max]of [['amplitude',0,2000],['cycles',.1,30],['turns',-20,20],['travelX',-4096,4096],['travelY',-4096,4096],['fadeIn',0,30],['fadeOut',0,30]])if(e[k]!==undefined&&!sf(e[k],min,max))err('Thông số chuyển động không hợp lệ: '+k);
  if(e.easing!==undefined&&!Object.hasOwn(SKILL_EASINGS,e.easing)||e.color!==undefined&&!/^#[0-9a-fA-F]{6}$/.test(e.color)||['visible','locked','smoothFrames'].some(k=>e[k]!==undefined&&typeof e[k]!=='boolean')||e.name!==undefined&&(typeof e.name!=='string'||e.name.length>100))err('Thiết lập mốc VFX không hợp lệ');ids.add(e.id)}}return p;
}
export function newVisualSkill(id='my_skill',name='Kỹ năng mới'){return {id,name,kind:'active',duration:1,cooldown:1,cost:0,range:300,hitAt:.4,animation:'attack',events:[]}}
export function skillFrame(effect,t){const frames=effect.frames||[];let at=0;for(let i=0;i<frames.length;i++){at+=frames[i].duration;if(t<at||i===frames.length-1)return frames[i]}return null}
export async function loadSkillImages(project,resolve=src=>src){const p=validateSkillProject(project),images=new Map();await Promise.all([...new Set(Object.values(p.effects).flatMap(e=>(e.frames||[]).map(f=>f.src)))].map(async src=>{const im=new Image();im.crossOrigin='anonymous';await new Promise((ok,no)=>{im.onload=()=>im.naturalWidth*im.naturalHeight<=16777216?ok():no(Error('Ảnh VFX quá lớn'));im.onerror=()=>no(Error('Không tải được ảnh VFX'));im.src=resolve(src)});images.set(src,im)}));return images}
export function motionEase(u,kind='linear'){u=Math.max(0,Math.min(1,u));return kind==='in'?u*u:kind==='out'?1-(1-u)**2:kind==='inOut'?u*u*(3-2*u):u}
export function skillEventTransform(e,instance,u=0){
 const d=motionDefaults(e.motion),k=motionEase(u,e.easing),amp=e.amplitude??d.amplitude,cycles=e.cycles??d.cycles,turns=e.turns??d.turns,tx=e.travelX??d.travelX,ty=e.travelY??d.travelY,angle=2*Math.PI*k,base=e.anchor==='caster'?(e.follow?instance.casterRef:instance.caster):e.anchor==='target'?instance.target:{x:0,y:0};
 let x=base.x+e.x,y=base.y+e.y,scale=e.scale,rotation=e.rotation;
 if(['projectile','arc','boomerang'].includes(e.motion)){const v=e.motion==='boomerang'?Math.sin(k*Math.PI):k;x=instance.caster.x+(instance.target.x-instance.caster.x)*v+e.x;y=instance.caster.y+(instance.target.y-instance.caster.y)*v+e.y;if(e.motion==='arc')y-=4*amp*k*(1-k)}
 else if(e.motion==='move'){x+=tx*k;y+=ty*k}else if(e.motion==='rise')y-=Math.abs(ty)*k;else if(e.motion==='fall')y-=Math.abs(ty)*(1-k);else if(e.motion==='sway')x+=amp*Math.sin(angle*cycles);else if(e.motion==='shake'){x+=amp*Math.sin(angle*cycles);y+=amp*.4*Math.sin(angle*cycles*1.7)}else if(e.motion==='orbit'){x+=amp*(Math.cos(angle*turns)-1);y+=amp*Math.sin(angle*turns)*.58}else if(e.motion==='spiral'){x+=amp*k*Math.cos(angle*turns);y+=amp*k*Math.sin(angle*turns)*.58}
 if(e.motion==='expand')scale*=.35+k*.9;else if(e.motion==='shrink')scale*=1-k*.9;else if(e.motion==='pulse')scale*=1+Math.min(.9,amp/100)*Math.sin(angle*cycles);if(e.motion==='spin')rotation+=360*turns*k;
 return {x,y,scale,rotation};
}
export function skillEventPosition(e,instance,u=0){const {x,y}=skillEventTransform(e,instance,u);return {x,y}}
export function skillEventActive(e,age){return e.visible!==false&&Number.isFinite(age)&&age>=0&&age<e.duration}
export function skillEventGeometry(e,fx,instance,age){
 if(!skillEventActive(e,age))return null;const tr=skillEventTransform(e,instance,age/e.duration);let x0=-120,y0=-120,x1=120,y1=120;
 if(fx.frames){const f=skillFrame(fx,age/e.duration*fx.frames.reduce((n,f)=>n+f.duration,0));x0=-f.ax*f.w;y0=-f.ay*f.h;x1=x0+f.w;y1=y0+f.h}else if(fx.primitive==='beam'){x0=-24;x1=24;y0=-262;y1=2}else if(fx.primitive==='slash'){y0=-140;y1=70}else if(fx.primitive==='ring'){x0=-(20+age/e.duration*100)-6;x1=-x0;y0=x0*.58;y1=-y0}else{y0=-220;y1=120}
 return {...tr,x0,y0,x1,y1};
}
export function hitSkillEvent(e,fx,instance,age,x,y,padding=0){const g=skillEventGeometry(e,fx,instance,age);if(!g)return false;const a=-g.rotation*Math.PI/180,dx=x-g.x,dy=y-g.y,lx=(dx*Math.cos(a)-dy*Math.sin(a))/g.scale,ly=(dx*Math.sin(a)+dy*Math.cos(a))/g.scale,p=padding/g.scale;return lx>=g.x0-p&&lx<=g.x1+p&&ly>=g.y0-p&&ly<=g.y1+p||Math.hypot(dx,dy)<=padding}
export function drawSkillEvent(ctx,e,fx,instance,age,images){
 if(!skillEventActive(e,age))return;const u=age/e.duration,pos=skillEventTransform(e,instance,u),fi=e.fadeIn??e.duration*.08,fo=e.fadeOut??e.duration*.18,fade=Math.min(1,fi>0?age/fi:1,fo>0?(e.duration-age)/fo:1),scale=pos.scale;ctx.save();try{ctx.translate(pos.x,pos.y);ctx.rotate(pos.rotation*Math.PI/180);ctx.scale(scale,scale);ctx.globalAlpha*=e.opacity*Math.max(0,fade);ctx.globalCompositeOperation=e.blend==='add'?'lighter':'source-over';if(fx.group!=='procedural'){const total=fx.frames.reduce((n,f)=>n+f.duration,0),f=skillFrame(fx,u*total),img=images.get(f.src);if(img)ctx.drawImage(img,-f.ax*f.w,-f.ay*f.h,f.w,f.h)}else{ctx.strokeStyle=(e.color||fx.color);ctx.fillStyle=(e.color||fx.color);ctx.lineWidth=6;ctx.shadowColor=(e.color||fx.color);ctx.shadowBlur=14;if(fx.primitive==='ring'){ctx.beginPath();ctx.ellipse(0,0,20+u*100,(20+u*100)*.58,0,0,Math.PI*2);ctx.stroke()}else if(fx.primitive==='slash'){ctx.beginPath();ctx.arc(0,-35,100,Math.PI*(.8+u),Math.PI*(1.7+u));ctx.stroke()}else if(fx.primitive==='beam'){ctx.globalAlpha*=.7;ctx.fillRect(-22,-260,44,260);ctx.fillStyle='#ffffff';ctx.fillRect(-6,-260,12,260)}else for(let i=0;i<14;i++){const a=i*2.399,r=20+u*140;ctx.beginPath();ctx.arc(Math.cos(a)*r,Math.sin(a)*r*.65-u*80,3*(1-u)+1,0,Math.PI*2);ctx.fill()}}}finally{ctx.restore()}
}
export class SkillPlayer{
 constructor(project,{onEvent=()=>{}}={}){this.project=validateSkillProject(project);this.onEvent=onEvent;this.time=0;this.instances=[];this.cooldowns=new Map();this.sequence=0}
 cast(id,{caster={x:0,y:0},target=caster}={}){if(!skillId(id)||!Object.hasOwn(this.project.skills,id))err('Chưa đăng ký skillId='+id);const s=this.project.skills[id];if(![caster.x,caster.y,target.x,target.y].every(Number.isFinite))err('Điểm phát skill không hợp lệ');if(s.kind==='passive'||this.remaining(id)>0||this.instances.length>=64)return null;const i={instanceId:++this.sequence,skillId:id,started:this.time,caster:{x:caster.x,y:caster.y},casterRef:caster,target:{x:target.x,y:target.y},hit:false};this.instances.push(i);this.cooldowns.set(id,this.time+s.cooldown);this.onEvent({type:'cast',skillId:id,instanceId:i.instanceId,animation:s.animation});return i}
 remaining(id){return Math.max(0,(this.cooldowns.get(id)||0)-this.time)}
 update(dt){if(!sf(dt,0,60))err('Bước thời gian skill phải từ 0–60 giây');this.time+=dt;for(const i of this.instances){const s=this.project.skills[i.skillId],age=this.time-i.started;if(!i.hit&&age>=s.hitAt){i.hit=true;this.onEvent({type:'hit-marker',skillId:i.skillId,instanceId:i.instanceId,target:{...i.target}})}}this.instances=this.instances.filter(i=>this.time-i.started<this.project.skills[i.skillId].duration)}
 draw(ctx,images,{layer='high'}={}){for(const i of this.instances){const s=this.project.skills[i.skillId],age=this.time-i.started;for(const e of s.events)if(e.layer===layer)drawSkillEvent(ctx,e,this.project.effects[e.effectId],i,age-e.at,images)}}
 clear(){this.instances=[];this.cooldowns.clear()}
}
